eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   LEARNING_MODULES: () => (/* binding */ LEARNING_MODULES)\n/* harmony export */ });\nconst LEARNING_MODULES = [\n    {\n        id: \"html-css\",\n        roleId: \"full-stack-dev\",\n        title: \"Semantic HTML5 & Modern CSS Systems\",\n        category: \"Frontend Foundations\",\n        description: \"Master semantic markup, modern CSS grid & flexbox layouts, CSS custom properties, WCAG 2.1 accessibility, and responsive fluid design.\",\n        progress: 100,\n        difficulty: \"Foundational\",\n        estimatedTime: \"8 hours\",\n        status: \"Completed\",\n        skillsCovered: [\n            \"HTML5\",\n            \"CSS3\",\n            \"Responsive Layouts\",\n            \"A11y Accessibility\",\n            \"Flexbox & Grid\"\n        ],\n        resources: [\n            {\n                id: \"res-1\",\n                title: \"Web Technologies & Semantic Architecture\",\n                provider: \"NPTEL\",\n                url: \"https://nptel.ac.in/courses/web-technologies\",\n                duration: \"3h 45m\",\n                type: \"Video\",\n                rating: 4.8,\n                language: \"English\"\n            },\n            {\n                id: \"res-2\",\n                title: \"Modern CSS Masterclass & Fluid Layouts\",\n                provider: \"IIT Madras Online\",\n                url: \"https://study.iitm.ac.in/courses/frontend-design\",\n                duration: \"2h 30m\",\n                type: \"Deep Dive\",\n                rating: 4.9,\n                language: \"English\"\n            },\n            {\n                id: \"res-3\",\n                title: \"MDN Web Docs: CSS Grid & Flexbox Complete Reference\",\n                provider: \"Official Docs\",\n                url: \"https://developer.mozilla.org/en-US/docs/Learn/CSS\",\n                duration: \"1h 15m\",\n                type: \"Documentation\",\n                rating: 5.0,\n                language: \"English\"\n            }\n        ],\n        topics: [\n            {\n                id: \"t1\",\n                title: \"Semantic Document Structure & Landmark Elements\",\n                completed: true,\n                duration: \"45m\",\n                summary: {\n                    en: \"Semantic HTML provides meaning to web structure, aiding screen readers and search engines with elements like <main>, <nav>, <article>, and <section>.\",\n                    ta: \"செமண்டிக் HTML வலைத்தளத்தின் கட்டமைப்பிற்கு பொருள் தருகிறது. <main>, <nav>, <article> போன்ற கூறுகள் வழியாக திரைப் படிப்பான் மற்றும் தேடுபொறிகளுக்கு உதவுகிறது.\",\n                    hi: \"सिमेंटिक HTML वेब संरचना को अर्थ देता है। <main>, <nav>, <article> और <section> जैसे तत्व स्क्रीन रीडर और एसईओ में मदद करते हैं।\",\n                    te: \"సెమాంటిక్ HTML వెబ్ నిర్మాణానికి స్పష్టతను ఇస్తుంది. <main>, <nav> లాంటి ట్యాగ్‌లు స్క్రీన్ రీడర్‌లకు సహాయపడతాయి.\",\n                    ml: \"വെബ് ഘടനയ്ക്ക് കൃത്യമായ അർത്ഥം നൽകുന്നതാണ് സിമാന്റിക് HTML. <main>, <nav> എന്നിവ സ്ക്രീൻ റീഡറുകൾക്ക് സഹായകമാണ്.\",\n                    kn: \"ಸೆಮ್ಯಾಂಟಿಕ್ HTML ವೆಬ್ ವಿನ್ಯಾಸಕ್ಕೆ ನಿಖರ ಅರ್ಥ ನೀಡುತ್ತದೆ. <main>, <nav> ಟ್ಯಾಗ್ ಗಳು ಸುಲಭ ಗ್ರಹಿಕೆಗೆ ನೆರವಾಗುತ್ತವೆ.\"\n                }\n            },\n            {\n                id: \"t2\",\n                title: \"CSS Grid vs Flexbox: Mental Models & 2D Layouts\",\n                completed: true,\n                duration: \"60m\",\n                summary: {\n                    en: \"Flexbox is 1-dimensional for rows or columns, while Grid is 2-dimensional for complex row/column placement with subgrid and auto-fit capabilities.\",\n                    ta: \"Flexbox 1-பரிமாண வரிசை/நெடுவரிசைக்கு பயன்படுகிறது, அதேசமயம் Grid 2-பரிமாண சிக்கலான பக்க அமைப்புகளுக்கு பயன்படுகிறது.\",\n                    hi: \"Flexbox 1-डायमेंशनल है जबकि Grid 2-डायमेंशनल लेआउट के लिए उपयोग किया जाता है।\",\n                    te: \"Flexbox 1-డైమెన్షనల్ కాగా, Grid 2-డైమెన్షనల్ లేఅవుట్‌లను సులభతరం చేస్తుంది.\",\n                    ml: \"Flexbox ഒരു വരിയിലോ കോളത്തിലോ ഉള്ള ഘടനയ്ക്കും, Grid 2-ഡൈമൻഷണൽ ലേഔട്ടുകൾക്കും ഉപയോഗിക്കുന്നു.\",\n                    kn: \"Flexbox 1-ಡೈಮೆನ್ಶನಲ್ ಮತ್ತು Grid 2-ಡೈಮೆನ್ಶನಲ್ ಲೇಔಟ್‌ಗಳಿಗೆ ಉಪಯುಕ್ತವಾಗಿದೆ.\"\n                }\n            }\n        ],\n        practiceExercise: {\n            title: \"Construct an Accessible Responsive Navigation Bar\",\n            problem: \"Write semantic HTML and modern CSS flexbox rules that support keyboard focus navigation, ARIA expanded state, and mobile burger toggle.\",\n            initialCode: `<nav aria-label=\"Main Navigation\">\\n  <ul class=\"nav-list\">\\n    <!-- Add navigation items with accessible links -->\\n  </ul>\\n</nav>`,\n            solutionCode: `<nav aria-label=\"Main Navigation\" class=\"flex items-center justify-between p-4 bg-night text-white border-b border-border\">\\n  <a href=\"/\" class=\"text-imperial font-bold text-lg\">SkillForge</a>\\n  <ul class=\"flex gap-6 text-white\">\\n    <li><a href=\"/learning\" class=\"hover:text-imperial transition-colors\">Learning</a></li>\\n    <li><a href=\"/projects\" class=\"hover:text-imperial transition-colors\">Projects</a></li>\\n  </ul>\\n</nav>`,\n            hints: [\n                \"Always provide an `aria-label` for multiple `<nav>` landmarks.\",\n                \"Use `:focus-visible` for accessible keyboard focus outlines.\"\n            ]\n        }\n    },\n    {\n        id: \"javascript-deep-dive\",\n        roleId: \"full-stack-dev\",\n        title: \"Modern JavaScript (ES6+) & Asynchronous Engine\",\n        category: \"Core Programming\",\n        description: \"Understand the V8 event loop, microtask queues, closures, prototypes, asynchronous concurrency with async/await, and functional programming idioms.\",\n        progress: 82,\n        difficulty: \"Intermediate\",\n        estimatedTime: \"14 hours\",\n        status: \"In Progress\",\n        skillsCovered: [\n            \"JavaScript\",\n            \"Event Loop\",\n            \"Promises / Async-Await\",\n            \"Closures\",\n            \"ES6 Modules\",\n            \"Memory Management\"\n        ],\n        resources: [\n            {\n                id: \"res-js-1\",\n                title: \"Programming in JavaScript & Web Architecture\",\n                provider: \"NPTEL\",\n                url: \"https://nptel.ac.in/courses/javascript-deep-dive\",\n                duration: \"5h 20m\",\n                type: \"Video\",\n                rating: 4.9,\n                language: \"English\"\n            },\n            {\n                id: \"res-js-2\",\n                title: \"Deep JavaScript Foundations & V8 Engine Internals\",\n                provider: \"Curated Video\",\n                url: \"https://youtube.com/watch?v=javascript-internals\",\n                duration: \"4h 10m\",\n                type: \"Deep Dive\",\n                rating: 4.8,\n                language: \"English\"\n            },\n            {\n                id: \"res-js-3\",\n                title: \"MDN JavaScript Guide & Specification\",\n                provider: \"Official Docs\",\n                url: \"https://developer.mozilla.org/en-US/docs/Web/JavaScript\",\n                duration: \"3h 00m\",\n                type: \"Documentation\",\n                rating: 5.0,\n                language: \"English\"\n            }\n        ],\n        topics: [\n            {\n                id: \"t-js-1\",\n                title: \"The V8 Event Loop, Call Stack & Microtask Ordering\",\n                completed: true,\n                duration: \"60m\",\n                summary: {\n                    en: \"The JS runtime handles synchronous code on the call stack, microtasks (Promises, queueMicrotask) immediately after each stack frame, and macrotasks (setTimeout, DOM events) in the next tick.\",\n                    ta: \"ஜாவாஸ்கிரிப்ட் கால் ஸ்டாக், மைக்ரோடாஸ்க்குகள் (ப்ராமிஸ்கள்) மற்றும் மேக்ரோடாஸ்க்குகள் (setTimeout) வரிசையாக செயல்படும் விதத்தை நிகழ்வு சுழற்சி (Event Loop) நிர்வகிக்கிறது.\",\n                    hi: \"इवेंट लूप कॉल स्टैक, माइक्रोटास्क (Promises) और मैक्रोटास्क (setTimeout) के निष्पादन क्रम को नियंत्रित करता है।\",\n                    te: \"ఈవెంట్ లూప్ కాల్ స్టాక్, మైక్రోటాస్క్‌లు మరియు మాక్రోటాస్క్‌ల క్రమాన్ని నిర్వహిస్తుంది.\",\n                    ml: \"ഇവന്റ് ലൂപ്പ് സമന്വയ കോഡും അസിൻക്രോണസ് മൈക്രോടാസ്കുകളും കൃത്യമായി ക്രമീകരിക്കുന്നു.\",\n                    kn: \"ಈವೆಂಟ್ ಲೂಪ್ ಕಾಲ್ ಸ್ಟ್ಯಾಕ್ ಮತ್ತು ಅಸಿಂಕ್ರೊನಸ್ ಟಾಸ್ಕ್‌ಗಳ ಕಾರ್ಯಗತಿಯನ್ನು ನಿಯಂತ್ರಿಸುತ್ತದೆ.\"\n                }\n            },\n            {\n                id: \"t-js-2\",\n                title: \"Closures, Lexical Scope & Garbage Collection\",\n                completed: true,\n                duration: \"50m\",\n                summary: {\n                    en: \"A closure is the combination of a function bundled together with references to its surrounding state (lexical environment), allowing private variables and factory patterns.\",\n                    ta: \"க்ளோஷர் (Closure) என்பது ஒரு சார்பு அதன் சுற்றியுள்ள லெக்சிகல் சூழல் மாறிகளை நினைவில் வைத்து செயல்படும் பண்பாகும்.\",\n                    hi: \"क्लोजर फ़ंक्शन और उसके लेक्सिकल एनवायरनमेंट का संयोजन है जो निजी वेरिएबल बनाने में सहायक होता है।\",\n                    te: \"క్లోజర్ అనేది ఒక ఫంక్షన్ మరియు దాని సరౌండింగ్ వేరియబుల్స్ కలయిక.\",\n                    ml: \"ഫംഗ്ഷനും അതിന്റെ അനുബന്ധ വേരിയബിളുകളും നിലനിർത്തുന്ന രീതിയാണ് ക്ലോഷർ.\",\n                    kn: \"ಕ್ಲೋಸರ್ ಎನ್ನುವುದು ಫಂಕ್ಷನ್ ತನ್ನ ಲೆಕ್ಸಿಕಲ್ ಪರಿಸರದ ವೇರಿಯೇಬಲ್‌ಗಳನ್ನು ಉಳಿಸಿಕೊಳ್ಳುವ ಗುಣಲಕ್ಷಣವಾಗಿದೆ.\"\n                }\n            },\n            {\n                id: \"t-js-3\",\n                title: \"Async Concurrency: Promise.all, allSettled, race & any\",\n                completed: false,\n                duration: \"55m\",\n                summary: {\n                    en: \"Master concurrency patterns: Promise.all fails fast on single rejection; Promise.allSettled guarantees results for all requests; Promise.race returns the fastest outcome.\",\n                    ta: \"Promise.all, allSettled, race மற்றும் any முறைகள் மூலம் பல வலை அழைப்புகளை ஒரே நேரத்தில் திறம்பட கையாளலாம்.\",\n                    hi: \"Promise.all और Promise.allSettled के माध्यम से कई समानांतर नेटवर्क कॉल्स को कुशलतापूर्वक प्रबंधित किया जाता है।\",\n                    te: \"Promise.all మరియు allSettled ద్వారా బహుళ నెట్‌వర్క్ అభ్యర్థనలను ఏకకాలంలో నిర్వహించవచ్చు.\",\n                    ml: \"ഒന്നിലധികം റിക്വസ്റ്റുകൾ ഒരേസമയം കൈകാര്യം ചെയ്യാൻ Promise കോൺകറൻസി മെത്തേഡുകൾ സഹായിക്കുന്നു.\",\n                    kn: \"Promise.all ಮುಂತಾದ ವಿಧಾನಗಳಿಂದ ಸಮಾನಾಂತರ ನೆಟ್‌ವರ್ಕ್ ಕಾಲ್‌ಗಳನ್ನು ನಿರ್ವಹಿಸಬಹುದು.\"\n                }\n            }\n        ],\n        practiceExercise: {\n            title: \"Implement a Resilient Exponential Backoff Retry Utility\",\n            problem: \"Write an asynchronous TypeScript helper function `fetchWithRetry(fn, maxRetries, baseDelayMs)` that catches transient errors and retries with doubling delays.\",\n            initialCode: `async function fetchWithRetry<T>(\\n  fn: () => Promise<T>,\\n  maxRetries = 3,\\n  baseDelayMs = 300\\n): Promise<T> {\\n  // Implement retry with exponential backoff\\n}`,\n            solutionCode: `async function fetchWithRetry<T>(\\n  fn: () => Promise<T>,\\n  maxRetries = 3,\\n  baseDelayMs = 300\\n): Promise<T> {\\n  let attempt = 0;\\n  while (attempt < maxRetries) {\\n    try {\\n      return await fn();\\n    } catch (err) {\\n      attempt++;\\n      if (attempt >= maxRetries) throw err;\\n      const delay = baseDelayMs * Math.pow(2, attempt - 1);\\n      await new Promise((res) => setTimeout(res, delay));\\n    }\\n  }\\n  throw new Error(\"Max retries exceeded\");\\n}`,\n            hints: [\n                \"Use `Math.pow(2, attempt)` for calculating delay.\",\n                \"Always re-throw the last error if all attempts fail.\"\n            ]\n        }\n    },\n    {\n        id: \"react-nextjs\",\n        roleId: \"full-stack-dev\",\n        title: \"React 18/19 & Next.js App Router Architecture\",\n        category: \"Frontend Frameworks\",\n        description: \"Architect stateful enterprise applications using Server/Client Components, custom hooks, Suspense streaming, error boundaries, and optimistic UI updates.\",\n        progress: 76,\n        difficulty: \"Intermediate\",\n        estimatedTime: \"16 hours\",\n        status: \"In Progress\",\n        skillsCovered: [\n            \"React\",\n            \"Next.js\",\n            \"Server Components\",\n            \"State Management\",\n            \"Hooks\",\n            \"Suspense\"\n        ],\n        resources: [\n            {\n                id: \"res-rc-1\",\n                title: \"React Architecture & Next.js Enterprise Patterns\",\n                provider: \"IIT Madras Online\",\n                url: \"https://study.iitm.ac.in/courses/react-architecture\",\n                duration: \"6h 15m\",\n                type: \"Deep Dive\",\n                rating: 4.9,\n                language: \"English\"\n            },\n            {\n                id: \"res-rc-2\",\n                title: \"Official Next.js App Router Documentation\",\n                provider: \"Official Docs\",\n                url: \"https://nextjs.org/docs/app\",\n                duration: \"3h 40m\",\n                type: \"Documentation\",\n                rating: 5.0,\n                language: \"English\"\n            },\n            {\n                id: \"res-rc-3\",\n                title: \"Interactive React Hook & Performance Lab\",\n                provider: \"Interactive Lab\",\n                url: \"https://skillforge.dev/labs/react-perf\",\n                duration: \"2h 30m\",\n                type: \"Exercise\",\n                rating: 4.8,\n                language: \"English\"\n            }\n        ],\n        topics: [\n            {\n                id: \"t-rc-1\",\n                title: \"React Server Components (RSC) vs Client Components\",\n                completed: true,\n                duration: \"60m\",\n                summary: {\n                    en: \"Server Components render on the server without sending JS bundles to the browser. Client Components ('use client') add interactive handlers, state, and browser APIs.\",\n                    ta: \"சர்வர் காம்போனென்ட்கள் பிரவுசருக்கு ஜாவாஸ்கிரிப்ட் அனுப்பாமல் சர்வரிலேயே ரெண்டர் ஆகின்றன. 'use client' உள்ளவை பயனாளர் ஊடாடலுக்கு பயன்படுகின்றன.\",\n                    hi: \"सर्वर कंपोनेंट्स बिना अतिरिक्त जावास्क्रिप्ट के सीधे सर्वर पर रेंडर होते हैं, जिससे परफॉरमेंस तेज होती है।\",\n                    te: \"సర్వర్ కాంపోనెంట్స్ బ్రౌజర్‌కు JS పంపకుండా సర్వర్‌లో రన్ అవుతాయి.\",\n                    ml: \"സെർവർ ഘടകങ്ങൾ സർവറിൽ മാത്രം പ്രവർത്തിച്ച് ബ്രൗസർ ലോഡ് കുറയ്ക്കുന്നു.\",\n                    kn: \"ಸರ್ವರ್ ಕಾಂಪೊನೆಂಟ್‌ಗಳು ಸರ್ವರ್‌ನಲ್ಲೇ ಕಾರ್ಯನಿರ್ವಹಿಸಿ ಬ್ರೌಸರ್ ವೇಗ ಹೆಚ್ಚಿಸುತ್ತವೆ.\"\n                }\n            },\n            {\n                id: \"t-rc-2\",\n                title: \"Custom Hook Composition & Cache Invalidation\",\n                completed: true,\n                duration: \"50m\",\n                summary: {\n                    en: \"Encapsulate reusable stateful logic into clean, type-safe custom hooks with predictable cleanup, abort controllers, and optimistic rollbacks.\",\n                    ta: \"மீண்டும் பயன்படுத்தக்கூடிய லாஜிக்கை கஸ்டம் ஹூக்குகளாக (Custom Hooks) மாற்றி எளிதாக மேலாண்மை செய்யலாம்.\",\n                    hi: \"कस्टम हुक्स के माध्यम से रियूजेबल स्टेट लॉजिक को संगठित और टाइप-सुरक्षित किया जाता है।\",\n                    te: \"కస్టమ్ హుక్స్ ద్వారా లాజిక్‌ను పునర్వినియోగించుకోవచ్చు.\",\n                    ml: \"കസ്റ്റം ഹുക്കുകൾ ഉപയോഗിച്ച് റീയൂസബിൾ ലോജിക് വൃത്തിയായി സൂക്ഷിക്കാം.\",\n                    kn: \"ಕಸ್ಟಮ್ ಹುಕ್‌ಗಳ ಮೂಲಕ ಕೋಡ್ ಮರುಬಳಕೆ ಸುಲಭವಾಗುತ್ತದೆ.\"\n                }\n            }\n        ],\n        practiceExercise: {\n            title: \"Build an Optimistic Upvote Hook with Error Rollback\",\n            problem: \"Implement `useOptimisticVote` that immediately increments UI state and reverts automatically if the simulated backend promise rejects.\",\n            initialCode: `function useOptimisticVote(initialVotes: number) {\\n  // Implement optimistic state with revert fallback\\n}`,\n            solutionCode: `function useOptimisticVote(initialVotes: number) {\\n  const [votes, setVotes] = React.useState(initialVotes);\\n  const [isPending, setIsPending] = React.useState(false);\\n  \\n  const vote = async (apiCall: () => Promise<void>) => {\\n    const previous = votes;\\n    setVotes((v) => v + 1);\\n    setIsPending(true);\\n    try {\\n      await apiCall();\\n    } catch (err) {\\n      setVotes(previous);\\n    } finally {\\n      setIsPending(false);\\n    }\\n  };\\n  return { votes, vote, isPending };\\n}`,\n            hints: [\n                \"Store previous state in a local variable before updating.\",\n                \"Use a try/catch/finally block to revert upon failure.\"\n            ]\n        }\n    },\n    {\n        id: \"nodejs-backend\",\n        roleId: \"full-stack-dev\",\n        title: \"Node.js, Express & Scalable Microservices\",\n        category: \"Backend Engineering\",\n        description: \"Engineer production-ready REST & RPC APIs, implement JWT/OAuth authentication, streaming pipelines, middleware chains, and rate limiting.\",\n        progress: 61,\n        difficulty: \"Intermediate\",\n        estimatedTime: \"15 hours\",\n        status: \"In Progress\",\n        skillsCovered: [\n            \"Node.js\",\n            \"Express\",\n            \"REST APIs\",\n            \"JWT Authentication\",\n            \"Middleware\",\n            \"Stream Processing\"\n        ],\n        resources: [\n            {\n                id: \"res-node-1\",\n                title: \"Cloud Computing & Backend Architecture\",\n                provider: \"NPTEL\",\n                url: \"https://nptel.ac.in/courses/backend-systems\",\n                duration: \"5h 40m\",\n                type: \"Video\",\n                rating: 4.8,\n                language: \"English\"\n            },\n            {\n                id: \"res-node-2\",\n                title: \"Node.js Official Diagnostics & Security Guide\",\n                provider: \"Official Docs\",\n                url: \"https://nodejs.org/en/docs/guides\",\n                duration: \"2h 45m\",\n                type: \"Documentation\",\n                rating: 4.9,\n                language: \"English\"\n            }\n        ],\n        topics: [\n            {\n                id: \"t-node-1\",\n                title: \"JWT Authentication, Refresh Token Rotation & Cookies\",\n                completed: true,\n                duration: \"60m\",\n                summary: {\n                    en: \"Short-lived access tokens (15 mins) stored in memory or HttpOnly cookies combined with rotated refresh tokens stored in Redis prevent session hijacking.\",\n                    ta: \"குறைந்த நேர அணுகல் டோக்கன்கள் மற்றும் புதுப்பிப்பு டோக்கன் சுழற்சி (Token Rotation) மூலம் பாதுகாப்பான பயனர் அமர்வை உருவாக்கலாம்.\",\n                    hi: \"सुरक्षित प्रमाणीकरण के लिए अल्पकालिक एक्सेस टोकन और रिफ्रेश टोकन रोटेशन का उपयोग किया जाता है।\",\n                    te: \"రీఫ్రెష్ టోకెన్ రొటేషన్ ద్వారా వినియోగదారు లాగిన్ భద్రతను మెరుగుపరచవచ్చు.\",\n                    ml: \"ആക്സസ് ടോക്കണുകളും റിഫ്രഷ് ടോക്കണുകളും ഉപയോഗിച്ച് സുരക്ഷിതമായ ലോഗിൻ ഉറപ്പാക്കാം.\",\n                    kn: \"ಟೋಕನ್ ರೊಟೇಶನ್ ಮೂಲಕ ಸುರಕ್ಷಿತ ಲಾಗಿನ್ ವ್ಯವಸ್ಥೆ ನಿರ್ಮಿಸಬಹುದು.\"\n                }\n            },\n            {\n                id: \"t-node-2\",\n                title: \"Stream Processing & Memory-Safe Large File Handlers\",\n                completed: false,\n                duration: \"55m\",\n                summary: {\n                    en: \"Node.js Streams process huge data chunks sequentially using pipe() and pipeline(), avoiding V8 out-of-memory heap crashes.\",\n                    ta: \"நோட்.ஜேஎஸ் ஸ்ட்ரீம்ஸ் (Streams) பெரிய அளவிலான கோப்புகளை நினைவக நெரிசல் இல்லாமல் துண்டு துண்டாக செயலாக்க உதவுகிறது.\",\n                    hi: \"स्ट्रीम्स बड़े डेटा फाइलों को बिना मेमोरी क्रैश किए टुकड़ों में प्रोसेस करने की सुविधा देती हैं।\",\n                    te: \"స్ట్రీమ్స్ ద్వారా మెమరీ సమస్యలు లేకుండా పెద్ద ఫైళ్ళను సులభంగా ప్రాసెస్ చేయవచ్చు.\",\n                    ml: \"വലിയ ഫയലുകൾ മെമ്മറി തകരാറുകൾ ഇല്ലാതെ പ്രോസസ്സ് ചെയ്യാൻ സ്ട്രീമുകൾ ഉപയോഗിക്കുന്നു.\",\n                    kn: \"ಸ್ಟ್ರೀಮ್ಸ್ ದೊಡ್ಡ ಫೈಲ್‌ಗಳನ್ನು ಮೆಮೊರಿ ದೋಷವಿಲ್ಲದೆ ಪ್ರಕ್ರಿಯೆಗೊಳಿಸುತ್ತವೆ.\"\n                }\n            }\n        ],\n        practiceExercise: {\n            title: \"Write an Express Rate Limiting Middleware using Memory Store\",\n            problem: \"Create a middleware `rateLimiter(windowMs, maxRequests)` that tracks IP request timestamps and returns HTTP 429 Too Many Requests if exceeded.\",\n            initialCode: `function rateLimiter(windowMs: number, maxRequests: number) {\\n  const ipHits = new Map<string, number[]>();\\n  return (req: any, res: any, next: any) => {\\n    // Implement sliding window rate limit check\\n  };\\n}`,\n            solutionCode: `function rateLimiter(windowMs: number, maxRequests: number) {\\n  const ipHits = new Map<string, number[]>();\\n  return (req: any, res: any, next: any) => {\\n    const ip = req.ip || '127.0.0.1';\\n    const now = Date.now();\\n    const windowStart = now - windowMs;\\n    const timestamps = (ipHits.get(ip) || []).filter((t) => t > windowStart);\\n    if (timestamps.length >= maxRequests) {\\n      return res.status(429).json({ error: 'Too many requests, please retry later.' });\\n    }\\n    timestamps.push(now);\\n    ipHits.set(ip, timestamps);\\n    next();\\n  };\\n}`,\n            hints: [\n                \"Filter timestamps older than `now - windowMs`.\",\n                \"Return HTTP 429 with informative JSON error.\"\n            ]\n        }\n    },\n    {\n        id: \"databases-sql\",\n        roleId: \"full-stack-dev\",\n        title: \"Relational Databases, PostgreSQL & Query Optimization\",\n        category: \"Data & Storage\",\n        description: \"Schema normalization, B-Tree and GIN indexing strategies, query plan analysis (EXPLAIN ANALYZE), ACID transactions, and connection pool sizing.\",\n        progress: 48,\n        difficulty: \"Intermediate\",\n        estimatedTime: \"12 hours\",\n        status: \"Recommended\",\n        skillsCovered: [\n            \"PostgreSQL\",\n            \"SQL\",\n            \"Schema Design\",\n            \"Indexing\",\n            \"Transactions\",\n            \"EXPLAIN ANALYZE\"\n        ],\n        resources: [\n            {\n                id: \"res-db-1\",\n                title: \"Database Management Systems & Query Processing\",\n                provider: \"NPTEL\",\n                url: \"https://nptel.ac.in/courses/dbms\",\n                duration: \"6h 30m\",\n                type: \"Video\",\n                rating: 4.9,\n                language: \"English\"\n            },\n            {\n                id: \"res-db-2\",\n                title: \"PostgreSQL High Performance Indexing & Query Tuning\",\n                provider: \"IIT Madras Online\",\n                url: \"https://study.iitm.ac.in/courses/postgres-perf\",\n                duration: \"4h 00m\",\n                type: \"Deep Dive\",\n                rating: 4.9,\n                language: \"English\"\n            }\n        ],\n        topics: [\n            {\n                id: \"t-db-1\",\n                title: \"B-Tree Indexes, Composite Keys & Covering Indexes\",\n                completed: true,\n                duration: \"50m\",\n                summary: {\n                    en: \"Indexes create balanced lookup trees. Multi-column indexes match queries from left-to-right (the leading column rule). Covering indexes (INCLUDE) eliminate table heap lookups.\",\n                    ta: \"இன்டெக்ஸ்கள் தேடுதல் வேகத்தை அதிகரிக்கின்றன. பல நெடுவரிசை இன்டெக்ஸ்களில் இடமிருந்து வலமாக முன்னுரிமை அளிக்கப்படுகிறது.\",\n                    hi: \"इंडेक्स सर्च की गति को बहुत तेज करते हैं। कवरिंग इंडेक्स टेबल हीप लुकअप को समाप्त करते हैं।\",\n                    te: \"ఇండెక్స్‌లు సెర్చ్ వేగాన్ని వేగవంతం చేస్తాయి. ಕవరింగ్ ఇండెక్స్‌లు డిస్క్ లోడ్‌ను తగ్గిస్తాయి.\",\n                    ml: \"ഡാറ്റാബേസ് സെർച്ച് വേഗത വർദ്ധിപ്പിക്കാൻ ഇൻഡെക്സുകൾ സഹായിക്കുന്നു.\",\n                    kn: \"ಇಂಡೆಕ್ಸ್‌ಗಳು ಶೋಧನೆಯ ವೇಗವನ್ನು ಹೆಚ್ಚಿಸಲು ಸಹಾಯ ಮಾಡುತ್ತವೆ.\"\n                }\n            },\n            {\n                id: \"t-db-2\",\n                title: \"ACID Isolation Levels & Preventing Race Conditions\",\n                completed: false,\n                duration: \"60m\",\n                summary: {\n                    en: \"Read Committed vs Repeatable Read vs Serializable. Use SELECT FOR UPDATE or optimistic locking with version columns to prevent double-spending race conditions.\",\n                    ta: \"டிரான்ஸாக்ஷன் தனிமைப்படுத்தல் நிலைகள் (Isolation Levels) மற்றும் ரேஸ் நிலைமைகளைத் தவிர்க்கும் முறைகள்.\",\n                    hi: \"ट्रांजैक्शन में डेटा विसंगतियों को रोकने के लिए आइसोलेशन लेवल्स और SELECT FOR UPDATE का उपयोग।\",\n                    te: \"ట్రాన్సాక్షన్లలో రేస్ కండిషన్లను నివారించడానికి ఐసోలేషన్ లెవెల్స్ ఉపయోగపడతాయి.\",\n                    ml: \"ഡാറ്റ കൃത്യത നിലനിർത്താൻ ഐസൊലേഷൻ ലെവലുകൾ ഉപയോഗിക്കുന്നു.\",\n                    kn: \"ಟ್ರಾನ್ಸಾಕ್ಷನ್‌ಗಳಲ್ಲಿ ಡೇಟಾ ದೋಷಗಳನ್ನು ತಡೆಯಲು ಐಸೋಲೇಶನ್ ಲೆವೆಲ್‌ಗಳು ಮುಖ್ಯ.\"\n                }\n            }\n        ],\n        practiceExercise: {\n            title: \"Write an Optimized SQL Aggregation Query with Window Functions\",\n            problem: \"Write a SQL query that ranks employees by salary within their respective department using `DENSE_RANK()` and finds the top 2 highest earners per dept.\",\n            initialCode: `-- Write SQL query using DENSE_RANK() OVER (PARTITION BY ...)\\n`,\n            solutionCode: `WITH RankedSalaries AS (\\n  SELECT \\n    id, name, department_id, salary,\\n    DENSE_RANK() OVER (PARTITION BY department_id ORDER BY salary DESC) as rank\\n  FROM employees\\n)\\nSELECT id, name, department_id, salary, rank\\nFROM RankedSalaries\\nWHERE rank <= 2\\nORDER BY department_id, rank;`,\n            hints: [\n                \"Use a Common Table Expression (CTE) with `WITH RankedSalaries AS (...)`\",\n                \"Filter `WHERE rank <= 2` in the outer query.\"\n            ]\n        }\n    },\n    {\n        id: \"rest-apis-graphql\",\n        roleId: \"full-stack-dev\",\n        title: \"RESTful API Standards, OpenAPI & Contracts\",\n        category: \"Backend Engineering\",\n        description: \"Design clean semantic REST APIs, versioning schemas (URI vs header), OpenAPI/Swagger specs, pagination patterns, and hypermedia controls.\",\n        progress: 69,\n        difficulty: \"Intermediate\",\n        estimatedTime: \"10 hours\",\n        status: \"In Progress\",\n        skillsCovered: [\n            \"REST APIs\",\n            \"OpenAPI / Swagger\",\n            \"Pagination\",\n            \"Versioning\",\n            \"HTTP Status Codes\"\n        ],\n        resources: [\n            {\n                id: \"res-api-1\",\n                title: \"Enterprise API Design Principles & Richardson Maturity Model\",\n                provider: \"Official Docs\",\n                url: \"https://swagger.io/resources/articles/best-practices-in-api-design/\",\n                duration: \"2h 30m\",\n                type: \"Documentation\",\n                rating: 4.8,\n                language: \"English\"\n            }\n        ],\n        topics: [\n            {\n                id: \"t-api-1\",\n                title: \"Cursor-Based vs Offset-Based Pagination at Scale\",\n                completed: true,\n                duration: \"45m\",\n                summary: {\n                    en: \"Offset pagination (OFFSET 100000) causes database table scanning and skips/duplicates when items are inserted; cursor pagination using indexed unique IDs is O(1) fast.\",\n                    ta: \"கர்சர் அடிப்படையிலான பேஜினேஷன் (Cursor Pagination) பெரிய அளவிலான தரவுகளுக்கு அதிவேகமானது மற்றும் நம்பகமானது.\",\n                    hi: \"कर्सर-आधारित पेजिनेशन बड़े डेटासेट के लिए ऑफसेट पेजिनेशन से बहुत अधिक कुशल है।\",\n                    te: \"కర్సర్ బేస్డ్ పేజినేషన్ పెద్ద డేటాబేస్‌లలో వేగంగా పనిచేస్తుంది.\",\n                    ml: \"വലിയ ഡാറ്റാബേസുകളിൽ കർസർ പേജിനേഷൻ കൂടുതൽ വേഗത നൽകുന്നു.\",\n                    kn: \"ಕರ್ಸರ್ ಪೇಜಿನೇಶನ್ ದೊಡ್ಡ ಪ್ರಮಾಣದ ಡೇಟಾಗೆ ಉತ್ತಮ ಪರಿಹಾರವಾಗಿದೆ.\"\n                }\n            }\n        ],\n        practiceExercise: {\n            title: \"Implement Cursor-Based Pagination Query Builder\",\n            problem: \"Construct an API response envelope returning `items`, `nextCursor`, and `hasMore` given an ordered collection of records.\",\n            initialCode: `function buildPaginatedEnvelope<T extends { id: string }>(items: T[], limit: number) {\\n  // Return pagination metadata\\n}`,\n            solutionCode: `function buildPaginatedEnvelope<T extends { id: string }>(items: T[], limit: number) {\\n  const hasMore = items.length > limit;\\n  const data = hasMore ? items.slice(0, limit) : items;\\n  const nextCursor = hasMore ? data[data.length - 1].id : null;\\n  return { data, hasMore, nextCursor, count: data.length };\\n}`,\n            hints: [\n                \"Fetch `limit + 1` records from database to detect `hasMore` without a separate COUNT query.\"\n            ]\n        }\n    },\n    {\n        id: \"git-version-control\",\n        roleId: \"full-stack-dev\",\n        title: \"Advanced Git, Branching Strategies & CI Workflows\",\n        category: \"DevOps & Tooling\",\n        description: \"Master interactive rebasing, merge conflict resolution, git bisect debugging, conventional commits, and GitHub Actions continuous integration gates.\",\n        progress: 88,\n        difficulty: \"Foundational\",\n        estimatedTime: \"6 hours\",\n        status: \"Completed\",\n        skillsCovered: [\n            \"Git\",\n            \"GitHub Actions\",\n            \"Interactive Rebase\",\n            \"Git Bisect\",\n            \"Trunk-Based Development\"\n        ],\n        resources: [\n            {\n                id: \"res-git-1\",\n                title: \"Pro Git: Advanced Branching & Plumbing Commands\",\n                provider: \"Official Docs\",\n                url: \"https://git-scm.com/book/en/v2\",\n                duration: \"3h 00m\",\n                type: \"Documentation\",\n                rating: 5.0,\n                language: \"English\"\n            }\n        ],\n        topics: [\n            {\n                id: \"t-git-1\",\n                title: \"Interactive Rebase, Cherry-Pick & Clean History\",\n                completed: true,\n                duration: \"40m\",\n                summary: {\n                    en: \"Use git rebase -i to squash intermediate WIP commits, reword commit messages, and produce a clean linear changelog before merging pull requests.\",\n                    ta: \"இன்டராக்டிவ் ரீபேஸ் (git rebase -i) மூலம் தேவையற்ற இடைநிலை கமிட்களை ஒன்றிணைத்து சுத்தமான வரலாற்றை உருவாக்கலாம்.\",\n                    hi: \"गिट रिबेस के माध्यम से कमिट हिस्ट्री को साफ और व्यवस्थित रखा जाता है।\",\n                    te: \"గిట్ రీబేస్ ద్వారా కమిట్ హిస్టరీని క్లీన్‌గా ఉంచవచ్చు.\",\n                    ml: \"ഗിറ്റ് റീബേസ് ഉപയോഗിച്ച് കമിറ്റ് ഹിസ്റ്ററി കൂടുതൽ ക്രമപ്പെടുത്താം.\",\n                    kn: \"ಗಿಟ್ ರಿಬೇಸ್ ಮೂಲಕ ಕಮಿಟ್ ಇತಿಹಾಸವನ್ನು ಸ್ವಚ್ಛವಾಗಿಡಬಹುದು.\"\n                }\n            }\n        ],\n        practiceExercise: {\n            title: \"Write a GitHub Actions CI Workflow for Automated Lint and Test\",\n            problem: \"Write a `.github/workflows/ci.yml` pipeline that triggers on pull requests to main, installs cached dependencies, runs type-checking, and executes Vitest.\",\n            initialCode: `name: CI Pipeline\\non: [pull_request]\\njobs:\\n  # Write job steps\\n`,\n            solutionCode: `name: CI Pipeline\\non:\\n  pull_request:\\n    branches: [main]\\njobs:\\n  test:\\n    runs-on: ubuntu-latest\\n    steps:\\n      - uses: actions/checkout@v4\\n      - uses: actions/setup-node@v4\\n        with:\\n          node-version: 20\\n          cache: 'npm'\\n      - run: npm ci\\n      - run: npm run lint\\n      - run: npm run test\\n`,\n            hints: [\n                \"Use `npm ci` rather than `npm install` in CI environments.\",\n                \"Enable `cache: 'npm'` for faster runner speeds.\"\n            ]\n        }\n    },\n    {\n        id: \"testing-qa\",\n        roleId: \"full-stack-dev\",\n        title: \"Unit, Integration & E2E Testing Methodologies\",\n        category: \"Quality Assurance\",\n        description: \"Implement Test-Driven Development (TDD) with Vitest/Jest, React Testing Library for accessibility assertions, and Playwright for real browser E2E test suites.\",\n        progress: 52,\n        difficulty: \"Intermediate\",\n        estimatedTime: \"11 hours\",\n        status: \"In Progress\",\n        skillsCovered: [\n            \"Vitest\",\n            \"Jest\",\n            \"React Testing Library\",\n            \"Playwright\",\n            \"Mock Service Worker (MSW)\"\n        ],\n        resources: [\n            {\n                id: \"res-test-1\",\n                title: \"Software Testing & Automated Quality Assurance\",\n                provider: \"NPTEL\",\n                url: \"https://nptel.ac.in/courses/software-testing\",\n                duration: \"4h 45m\",\n                type: \"Video\",\n                rating: 4.8,\n                language: \"English\"\n            }\n        ],\n        topics: [\n            {\n                id: \"t-test-1\",\n                title: \"Mocking Network Requests with Mock Service Worker (MSW)\",\n                completed: true,\n                duration: \"50m\",\n                summary: {\n                    en: \"MSW intercepts network calls at the network level via Service Workers, allowing tests to run against realistic API behavior without fragile monkey-patching.\",\n                    ta: \"MSW நெட்வொர்க் மட்டத்தில் API அழைப்புகளை இடைமறித்து உண்மையான பரிசோதனைகளை நடத்த உதவுகிறது.\",\n                    hi: \"MSW नेटवर्क स्तर पर API कॉल्स को इंटरसेप्ट करके सटीक परीक्षण वातावरण प्रदान करता है।\",\n                    te: \"MSW ద్వారా రియలిస్టిక్ API టెస్టింగ్‌ను సులభంగా చేయవచ్చు.\",\n                    ml: \"യഥാർത്ഥ നെറ്റ്‌വർക്ക് കോളുകൾ സിമുലേറ്റ് ചെയ്യാൻ MSW സഹായിക്കുന്നു.\",\n                    kn: \"MSW ನೆಟ್‌ವರ್ಕ್ ಕಾಲ್‌ಗಳನ್ನು ಇಂಟರ್‌ಸೆಪ್ಟ್ ಮಾಡಿ ಪರೀಕ್ಷೆ ಸುಲಭವಾಗಿಸುತ್ತದೆ.\"\n                }\n            }\n        ],\n        practiceExercise: {\n            title: \"Write a React Testing Library Test for Form Submission\",\n            problem: \"Write a test asserting that submitting a login form with valid credentials triggers the onSubmit callback with the typed username and password.\",\n            initialCode: `test('submits credentials when user clicks login', async () => {\\n  // Write RTL test using userEvent and screen\\n});`,\n            solutionCode: `test('submits credentials when user clicks login', async () => {\\n  const handleSubmit = vi.fn();\\n  render(<LoginForm onSubmit={handleSubmit} />);\\n  await userEvent.type(screen.getByLabelText(/email/i), 'hamenath@example.com');\\n  await userEvent.type(screen.getByLabelText(/password/i), 'SecurePass123!');\\n  await userEvent.click(screen.getByRole('button', { name: /log in/i }));\\n  expect(handleSubmit).toHaveBeenCalledWith({\\n    email: 'hamenath@example.com',\\n    password: 'SecurePass123!',\\n  });\\n});`,\n            hints: [\n                \"Prefer `getByRole` and `getByLabelText` to encourage accessible DOM attributes.\"\n            ]\n        }\n    },\n    {\n        id: \"docker-cloud-deploy\",\n        roleId: \"full-stack-dev\",\n        title: \"Docker Containerization & Production Cloud Deployment\",\n        category: \"DevOps & Cloud\",\n        description: \"Write lean Alpine Dockerfiles, compose multi-container stacks (App + Postgres + Redis), configure Nginx reverse proxies with SSL, and deploy to AWS / Render / Vercel.\",\n        progress: 40,\n        difficulty: \"Intermediate\",\n        estimatedTime: \"10 hours\",\n        status: \"Recommended\",\n        skillsCovered: [\n            \"Docker\",\n            \"Docker Compose\",\n            \"Nginx\",\n            \"SSL / TLS\",\n            \"Cloud Deployment\",\n            \"Healthchecks\"\n        ],\n        resources: [\n            {\n                id: \"res-dock-1\",\n                title: \"Containerization & Cloud Native Architecture\",\n                provider: \"IIT Madras Online\",\n                url: \"https://study.iitm.ac.in/courses/cloud-native\",\n                duration: \"5h 00m\",\n                type: \"Deep Dive\",\n                rating: 4.9,\n                language: \"English\"\n            }\n        ],\n        topics: [\n            {\n                id: \"t-dock-1\",\n                title: \"Layer Caching & Multi-Stage Dockerfile Optimization\",\n                completed: false,\n                duration: \"45m\",\n                summary: {\n                    en: \"Order Dockerfile instructions from least frequently changing (package.json) to most frequently changing (source code) to maximize Docker layer cache hits.\",\n                    ta: \"டாக்கர்பைல் வழிமுறைகளை சரியான வரிசையில் அமைப்பதன் மூலம் கேச் (Cache) பயன்பாட்டை அதிகரித்து வேகமான உருவாக்கத்தை பெறலாம்.\",\n                    hi: \"डॉकर्फाइल में लेयर कैशिंग का सही उपयोग बिल्ड समय को काफी कम कर देता है।\",\n                    te: \"డాకర్ లేయర్ క్యాషింగ్ ద్వారా బిల్డ్ సమయాన్ని తగ్గించవచ్చు.\",\n                    ml: \"ഡോക്കർ കാഷിംഗ് ബിൽഡ് വേഗത വർദ്ധിപ്പിക്കുന്നു.\",\n                    kn: \"ಡಾಕರ್ ಲೇಯರ್ ಕ್ಯಾಶಿಂಗ್ ಬಿಲ್ಡ್ ವೇಗವನ್ನು ಗಣನೀಯವಾಗಿ ಹೆಚ್ಚಿಸುತ್ತದೆ.\"\n                }\n            }\n        ],\n        practiceExercise: {\n            title: \"Write a Multi-Stage Dockerfile for Next.js Standalone Build\",\n            problem: \"Create a 3-stage Dockerfile (deps, builder, runner) using `node:20-alpine` with non-root security execution.\",\n            initialCode: `# Multi-stage Dockerfile for Next.js\\n`,\n            solutionCode: `FROM node:20-alpine AS base\\nWORKDIR /app\\n\\nFROM base AS deps\\nCOPY package*.json ./\\nRUN npm ci\\n\\nFROM base AS builder\\nCOPY --from=deps /app/node_modules ./node_modules\\nCOPY . .\\nRUN npm run build\\n\\nFROM base AS runner\\nENV NODE_ENV=production\\nRUN addgroup --system --gid 1001 nodejs\\nRUN adduser --system --uid 1001 nextjs\\nCOPY --from=builder --chown=nextjs:nodejs /app/.next/standalone ./\\nCOPY --from=builder --chown=nextjs:nodejs /app/public ./public\\nCOPY --from=builder --chown=nextjs:nodejs /app/.next/static ./.next/static\\nUSER nextjs\\nEXPOSE 3000\\nCMD [\"node\", \"server.js\"]`,\n            hints: [\n                \"Create and switch to a non-root user `nextjs` in the runner stage.\",\n                \"Use Next.js standalone output mode.\"\n            ]\n        }\n    }\n];\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/data/learning.ts\n");

